  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');

  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);

  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');

  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);
  };

  const load = async (endpoint) => {
    if (!endpoint) return [];
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: Array.isArray(course.students) ? course.students.map(Number) : []
        }));
        setCourses(fetched);
      }

      return fetched;
    } catch (err) {
      console.error(err);
      return [];
    } finally {
      setLoading(false);
    }
  };

  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);

    const endpoint = getEndpoint(newPage);
    if (endpoint) {
      let fetched = await load(endpoint);
      setData(fetched);

      if (user?.role === 'student') {
        if (newPage === 'assignments' || newPage === 'announcements') {
          const filtered = fetched.filter(item => enrolledCourseIds.includes(item.courseid));
          setData(filtered);
        }
      }
    }
  };

  useEffect(() => {
    if (user) {
      load('courses').then(fetchedCourses => {
        const enrolledIds = fetchedCourses
          .filter(c => (c.students || []).includes(user.id))
          .map(c => c.id);
        setEnrolledCourseIds(enrolledIds);
      });

      goTo('courses');
    }
  }, [user]);

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => [...prev, courseId]);
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  const submitAssignment = async (assignmentId) => {
    if (!submissionText.trim()) {
      alert('Please write your answer before submitting.');
      return;
    }
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: submissionText
      });
      alert('Assignment submitted successfully!');
      setSubmissionText('');
      setSelectedAssignment(null);
      if (page === 'submissions') goTo('submissions');
    } catch (err) {
      alert('Submission failed');
    }
  };

  const viewSubmission = (text, submissionId) => {
    if (text && text.trim()) {
      setCurrentSubmissionText(text.trim());
      setCurrentSubmissionId(submissionId);
      setShowFileModal(true);
    } else {
      alert('No submission yet.');
    }
  };

  const requestDeleteSubmission = (submissionId) => {
    setItemToDelete(submissionId);
    setDeleteBase('submissions');
    setShowConfirmDelete(true);
  };

  const gradeSubmission = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const saveGrade = async () => {
    if (!gradeValue || isNaN(gradeValue) || parseInt(gradeValue) < 0 || parseInt(gradeValue) > 100) {
      alert('Please enter a valid grade (0-100)');
      return;
    }

    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: parseInt(gradeValue),
        feedback: feedbackText
      });
      alert('Grade saved successfully!');
      setShowGradeModal(false);
      setGradeValue('');
      setFeedbackText('');
      setSubmissionToGrade(null);
      await goTo('submissions');
    } catch (err) {
      alert('Failed to save grade');
    }
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete}`);
      alert('Deleted successfully');
      setShowConfirmDelete(false);
      setItemToDelete(null);
      setDeleteBase('');
      setCurrentSubmissionId(null);
      setShowFileModal(false);
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students') payload.role = 'student';

    if ((page === 'announcements' || page === 'assignments') && !payload.courseid) {
      alert('Please select a valid course.');
      return;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Invalid data'));
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Login Screen */}
      {page === 'login' && !user && (
        <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 to-indigo-700">
          <div className="bg-white p-10 rounded-2xl shadow-2xl w-full max-w-md">
            <h1 className="text-4xl font-bold text-center text-gray-800 mb-8">NM Student Portal</h1>
            <form onSubmit={login} className="space-y-6">
              <input
                type="email"
                placeholder="Enter your email"
                value={emailInput}
                onChange={(e) => setEmailInput(e.target.value)}
                required
                className="w-full px-5 py-4 border border-gray-300 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-300 text-lg"
              />
              <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-blue-700 transition">
                Login
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Dashboard */}
      {user && (
        <div className="flex h-screen bg-gray-100">
          {/* Sidebar */}
          <aside className="w-72 bg-white shadow-xl">
            <div className="p-8 border-b border-gray-200">
              <h2 className="text-3xl font-bold text-blue-600">NM Portal</h2>
              <p className="text-gray-600 mt-2">Welcome, <span className="font-semibold">{user.name}</span></p>
              <p className="text-sm text-gray-500">({user.role})</p>
            </div>
            <nav className="p-4">
              <button onClick={() => goTo('courses')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'courses' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                📚 Courses
              </button>
              {user.role === 'student' && (
                <>
                  <button onClick={() => goTo('assignments')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'assignments' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    📝 Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'announcements' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    📢 Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'submissions' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    📤 My Submissions
                  </button>
                </>
              )}
              {user.role === 'instructor' && (
                <>
                  <button onClick={() => goTo('assignments')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'assignments' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    📝 Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'announcements' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    📢 Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'submissions' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    ✅ Grade Submissions
                  </button>
                  <button onClick={() => goTo('students')} className={`w-full text-left px-6 py-4 rounded-lg mb-2 transition ${page === 'students' ? 'bg-blue-100 text-blue-700 font-semibold' : 'hover:bg-gray-100'}`}>
                    👥 Students
                  </button>
                </>
              )}
              <button onClick={logout} className="w-full text-left px-6 py-4 mt-8 text-red-600 hover:bg-red-50 rounded-lg transition">
                🚪 Logout
              </button>
            </nav>
          </aside>

          {/* Main Content Area */}
          <main className="flex-1 overflow-y-auto">
            <header className="bg-white shadow-sm px-10 py-8">
              <div className="flex justify-between items-center">
                <h1 className="text-4xl font-bold text-gray-800">{page.charAt(0).toUpperCase() + page.slice(1)}</h1>
                {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
                  <button onClick={startAdd} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-semibold hover:bg-blue-700 transition shadow-md">
                    + Add New {page.slice(0, -1)}
                  </button>
                )}
              </div>
            </header>

            <div className="p-10">
              {loading && <p className="text-center text-gray-600 text-lg">Loading...</p>}

              {!loading && data.length === 0 && (
                <div className="text-center py-20">
                  <p className="text-2xl text-gray-500">No {page} available yet.</p>
                </div>
              )}

              {data.length > 0 && (
                <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
                  {data.map(item => (
                    <div key={item.id} className="bg-white rounded-2xl shadow-lg p-8 hover:shadow-2xl transition duration-300">
                      <h3 className="text-2xl font-bold text-gray-800 mb-3">{item.title || `Item ${item.id}`}</h3>
                      <p className="text-gray-700 mb-4">{item.description || item.message || 'No description'}</p>
                      {item.duedate && <p className="text-sm text-gray-500 mb-2"><strong>Due:</strong> {item.duedate}</p>}
                      {item.courseid && <p className="text-sm text-gray-500 mb-4"><strong>Course ID:</strong> {item.courseid}</p>}

                      {/* Actions */}
                      <div className="flex flex-wrap gap-3 mt-6">
                        {page === 'courses' && user.role === 'instructor' && (
                          <>
                            <button onClick={() => startEdit(item)} className="px-5 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition">Edit</button>
                            <button onClick={() => requestDeleteSubmission(item.id, 'courses')} className="px-5 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition">Delete</button>
                          </>
                        )}
                        {page === 'courses' && user.role === 'student' && (
                          <button
                            onClick={() => (item.students || []).includes(user.id) ? drop(item.id) : enroll(item.id)}
                            className={`px-8 py-3 rounded-lg font-semibold transition ${ (item.students || []).includes(user.id) ? 'bg-orange-600 hover:bg-orange-700' : 'bg-green-600 hover:bg-green-700' } text-white`}
                          >
                            {(item.students || []).includes(user.id) ? 'Drop Course' : 'Enroll'}
                          </button>
                        )}

                        {/* Add more actions for other pages similarly */}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </main>
        </div>
      )}

      {/* Keep all your existing modals here with updated styling */}
      {/* (Submission modal, view modal, grade modal, form modal, delete confirmation, etc.) */}
    </div>
  );
}

export default App;
